<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientDynamicallyRegisteredAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientDynamicallyRegisteredAccessor trait.
 *
 * Covers null default, string/VO assignment via withDynamicallyRegistered,
 * getDynamicallyRegistered/dynamicallyRegistered accessors, and isDynamicallyRegisteredChanged with/without original.
 */
class TrustedClientDynamicallyRegisteredAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withDynamicallyRegistered creates a new instance with the DynamicallyRegistered set
     * from a string value, and getDynamicallyRegistered returns the primitive string.
     */
    public function testWithDynamicallyRegisteredFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDynamicallyRegisteredAccessorUnitTest();

        // Act
        $result = $holder->withDynamicallyRegistered(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isDynamicallyRegistered());
    }
    /**
     * Asserts that withdynamicallyRegistered has access to the value object
     * from a string value, and getDynamicallyRegistered returns the primitive string.
     */
    public function testWithDynamicallyRegisteredFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDynamicallyRegisteredAccessorUnitTest();

        // Act
        $result = $holder->withDynamicallyRegistered(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->dynamicallyRegistered()->value());
    }
    public function testChangedDynamicallyRegistered(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientDynamicallyRegisteredAccessorUnitTest();
        $original = $holder->withDynamicallyRegistered(true);
        $same = $holder->withDynamicallyRegistered(true);
        $modified = $holder->withDynamicallyRegistered(false);

        // Act
        $unchanged = $holder->isDynamicallyRegisteredChanged();
        $withSame = $original->isDynamicallyRegisteredChanged($same);
        $withDiferent = $original->isDynamicallyRegisteredChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientDynamicallyRegisteredAccessorUnitTest
{
    use TrustedClientDynamicallyRegisteredAccessor;
}
